// Evidence checked on PubMed (29 Oct 2026). Summa quotations: Dominican translation, checked by script against New Advent.
addTerms([
 {id:"emdr",t:"EMDR (Eye Movement Desensitisation and Reprocessing)",la:"",d:"Psychology",b:"A trauma-focused therapy in which the client briefly holds a traumatic memory in mind while attending to bilateral stimulation (usually eye movements), within an eight-phase protocol.",p:"Developed by Francine Shapiro (1989). Its rationale is the Adaptive Information Processing model: unprocessed memories drive symptoms and can be reprocessed. Recommended for PTSD by WHO (2013), ISTSS (2019) and NICE (2018); Lewis et al. (2020) found robust evidence of a clinically important effect. Whether the eye movements add anything beyond imaginal exposure remains debated.",ex:"Recalling the image of an assault, its negative belief ('I am powerless'), and bodily sensation, while tracking the therapist's fingers.",where:"Lewis et al. (2020); WHO (2013)",ccc:"",conf:"Hypnosis; 'erasing' memories.",rel:["ptsd","exposure-therapy"],lesson:"p16",alias:["EMDR","eye movement desensitization","Adaptive Information Processing"]},
 {id:"ptsd",t:"PTSD and complex PTSD",la:"",d:"Psychology",b:"Disorders following trauma: re-experiencing, avoidance, and a sense of current threat (PTSD); plus disturbances in self-organisation (complex PTSD, ICD-11).",p:"ICD-11 6B40 PTSD: re-experiencing in the present, avoidance, persistent sense of current threat. 6B41 complex PTSD adds affect dysregulation, negative self-concept and relational disturbance, usually after prolonged or repeated trauma. DSM-5-TR PTSD has four clusters (intrusion, avoidance, negative cognitions/mood, arousal) and no separate complex PTSD.",ex:"Flashbacks and hypervigilance after a hijacking.",where:"ICD-11; DSM-5-TR",ccc:"",conf:"Ordinary distress after trauma, which usually remits.",rel:["emdr","exposure-therapy"],lesson:"p16",alias:["PTSD","complex PTSD","CPTSD","post-traumatic stress disorder","trauma"]},
 {id:"mania",t:"Mania and hypomania",la:"",d:"Psychology",b:"Distinct periods of abnormally elevated, expansive or irritable mood with increased energy, lasting at least a week (mania) or four days (hypomania).",p:"Symptoms: grandiosity, decreased need for sleep, pressured speech, racing thoughts, distractibility, increased goal-directed activity, risky behaviour. Mania causes marked impairment or psychosis; hypomania does not. Bipolar I requires mania; bipolar II requires hypomania and major depression.",ex:"Sleeping two hours a night for a week, spending savings, believing oneself chosen for a world mission.",where:"DSM-5-TR; ICD-11 6A60–6A61",ccc:"",conf:"Ordinary happiness or enthusiasm; spiritual consolation.",rel:["imputability"],lesson:"p17",alias:["mania","hypomania","bipolar disorder","manic episode"]},
 {id:"executive-function",t:"Executive functions",la:"",d:"Psychology",b:"The top-down mental processes that manage goal-directed behaviour: inhibition, working memory, and cognitive flexibility.",p:"Miyake et al. (2000) found three related but separable components (inhibition, updating/working memory, shifting). Planning and self-regulation build on them. Weaknesses are common, though not universal, in ADHD.",ex:"Holding a phone number in mind while dialling; stopping oneself from interrupting.",where:"Miyake et al. (2000); Diamond (2013)",ccc:"",conf:"Intelligence (related but distinct).",rel:["prudence"],lesson:"p18",alias:["executive function","executive functions","working memory","inhibitory control","self-regulation"]},
 {id:"inclusive-education",t:"Inclusive education (South Africa)",la:"",d:"Psychology",b:"Educating learners with disabilities and learning barriers within ordinary schools as far as possible, with graded support.",p:"Education White Paper 6 (2001) set out an inclusive system: full-service schools, special schools as resource centres, and district-based support teams. The Policy on Screening, Identification, Assessment and Support (SIAS, 2014) standardises how support needs are identified and met.",ex:"An autistic learner attending a full-service school with a learning-support educator and adapted assessment.",where:"White Paper 6 (2001); SIAS (2014)",ccc:"",conf:"Integration without support (placement only).",rel:["executive-function"],lesson:"p19",alias:["inclusive education","White Paper 6","SIAS","full-service school"]}
]);

